@startuml

class Airline {
  + ID : string
}

class Airport {
  + ID : string
}

class Flight {
  + ID : string
  + DepartureTime : time
  + ArrivalTime : time
}

class Aircraft {
  + Type : string
  + IsWorking : boolean
  + IsAirborne : boolean
}

class Pilot {
  + ExperienceLevel : int
}

class RoleRequirement {
  + Role : string
  + MinPilots : int
}

Airline "1" -- "*" Flight
Airline "1" *-- "*" Aircraft
Airline "1" -- "*" Pilot
Flight "1" -- "1" Airport : departure
Flight "1" -- "1" Airport : arrival
Flight "1" -- "1" Pilot : captain
Flight "1" -- "1..2" Pilot : co-pilot
Flight "1" -- "1" Aircraft
Aircraft "*" -- "1" RoleRequirement

@enduml

